import React, { useEffect, useState, useMemo, useCallback } from 'react';
import '../styles/Gantt.css';
import '../styles/List.css';
import { RESERVATIONS_URL } from '../config';
import { useLocation } from './AreaContext';

const formatUTCDate = () => {
    const date = new Date();
    const day = String(date.getUTCDate()).padStart(2, '0');
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const year = date.getUTCFullYear();
    return `${day}/${month}/${year}`;
};

const formatTime = (date) => {
    const hours = date.getUTCHours().toString().padStart(2, '0');
    const minutes = date.getUTCMinutes().toString().padStart(2, '0');
    return `${hours}:${minutes}`;
};

const getStartOfHour = (date) => {
    const startOfHour = new Date(date);
    startOfHour.setUTCMinutes(0, 0, 0);
    return startOfHour;
};

const Gantt = () => {
    const [resources, setResources] = useState([]);
    const [events, setEvents] = useState([]);
    const [startDate, setStartDate] = useState(getStartOfHour(new Date()).toISOString());
    const [utcTime, setUtcTime] = useState(formatUTCDate());
    const { selectedLocation } = useLocation();

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await fetch(`${RESERVATIONS_URL}${selectedLocation}.json`);
                const data = await response.json();
                const resourceMap = {};
                const eventList = [];
                let earliestStartDate = new Date();

                data.forEach(reservation => {
                    reservation.areas.forEach(area => {
                        if (!resourceMap[area.area_id]) {
                            resourceMap[area.area_id] = {
                                name: area.area_id,
                                id: area.area_id,
                                children: []
                            };
                        }

                        const lower = area.lower === 0 ? 'SFC' : area.lower < 100 ? `FL0${area.lower}` : `FL${area.lower}`;
                        const upper = area.upper === 999 ? 'UNL' : area.upper < 100 ? `FL0${area.upper}` : `FL${area.upper}`;

                        let start = new Date(reservation.start);
                        const end = new Date(reservation.end);

                        // Adjust start time if it is in the past
                        const now = new Date();
                        if (start < now) {
                            start.setUTCHours(Math.floor(now.getUTCHours()), 0, 0, 0);
                        }

                        if (start < earliestStartDate) {
                            earliestStartDate = start;
                        }

                        eventList.push({
                            start: start.toISOString(),
                            end: end.toISOString(),
                            id: `${reservation.reservation_id}-${area.area_id}`,
                            text: `${lower} - ${upper}`,
                            status: reservation.status,
                            resource: area.area_id
                        });
                    });
                });

                setResources(Object.values(resourceMap));
                setEvents(eventList);
                setStartDate(getStartOfHour(earliestStartDate).toISOString());
            } catch (error) {
                console.error('Error fetching data:', error);
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        const interval = setInterval(() => {
            setUtcTime(formatUTCDate());
            const now = new Date();
            if (now.getUTCMinutes() === 0) {
                setStartDate(getStartOfHour(now).toISOString());
            }
        }, 60000); // Update every minute

        return () => clearInterval(interval); // Cleanup interval on component unmount
    }, []);

    const renderEvents = useCallback((resourceId, cellStart) => {
        const cellEvents = events.filter(event => {
            const eventStart = new Date(event.start);
            const eventEnd = new Date(event.end);
            return event.resource === resourceId && eventStart < cellStart && eventEnd >= cellStart;
        });
    
        return cellEvents.map(event => {
            let start = new Date(event.start);
            const end = new Date(event.end);
            const left = ((start - cellStart) / (1000 * 60 * 60)) * 100;
            const width = ((end - start) / (1000 * 60 * 60)) * 100;
    
            return (
                <div
                    key={event.id}
                    className={`gantt-event gantt-event-${event.status}`}
                    style={{ left: `${left}%`, width: `${width}%` }}
                >
                    {event.text}
                </div>
            );
        });
    }, [events]);
    
    const renderCells = useCallback((resourceId) => {
        const cells = [];
        const start = new Date(startDate);
        const end = new Date(startDate);
        end.setDate(end.getDate() + 2);

        while (start < end) {
            cells.push(
                <div key={start.toISOString()} className="gantt-cell">
                    {renderEvents(resourceId, start)}
                </div>
            );
            start.setHours(start.getHours() + 1);
        }

        return cells;
    }, [startDate, renderEvents]);

    const renderRows = useMemo(() => {
        return resources.map(resource => (
            <div key={resource.id} className="gantt-row">
                <div className="gantt-resource-header">{resource.name}</div>
                {renderCells(resource.id)}
            </div>
        ));
    }, [resources, renderCells]);

    const renderHeader = useMemo(() => {
        const headers = [];
        const start = new Date(startDate);
        const end = new Date(startDate);
        end.setDate(end.getDate() + 2);

        while (start < end) {
            headers.push(
                <div key={start.toISOString()} className="gantt-header-cell">
                    <p className='time-text'>{formatTime(start)}</p>
                </div>
            );
            start.setHours(start.getHours() + 1);
        }

        return headers;
    }, [startDate]);

    return (
        <div className="list-container">
            <div className="gantt-container">
                <div className="gantt-header">
                    <div className="gantt-resource-header">{utcTime}</div>
                    {renderHeader}
                </div>
                <div className="gantt-body">
                    {renderRows}
                </div>
            </div>
        </div>
    );
};

export default Gantt;
